def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    def min_changes(substring):
        n = len(substring)
        min_changes = float('inf')
        for d in range(1, n):
            if n % d == 0:
                changes = 0
                for i in range(d):
                    chars = [substring[j] for j in range(i, n, d)]
                    count = {}
                    for char in chars:
                        if char not in count:
                            count[char] = 0
                        count[char] += 1
                    max_count = max(count.values())
                    changes += len(chars) - max_count
                min_changes = min(min_changes, changes)
        return min_changes if min_changes != float('inf') else 0

    memo = {}
    def dp(i, j):
        if (i, j) in memo:
            return memo[(i, j)]
        if i == 0 and j == 0:
            return 0
        if i < j or j == 0:
            return float('inf')
        ans = float('inf')
        for m in range(i):
            ans = min(ans, dp(m, j - 1) + min_changes(s[m:i]))
        memo[(i, j)] = ans
        return ans

    return dp(len(s), k)

