def count_good_strings(n: int, k: int, s: str) -> int:
    MOD = 998244353

    def is_palindrome(substring):
        return substring == substring[::-1]

    dp = {}

    def backtrack(index, current_string):
        if index == n:
            return 1 if not any(is_palindrome(current_string[i:i+k]) for i in range(n-k+1)) else 0

        if (index, current_string) in dp:
            return dp[(index, current_string)]

        if s[index] != '?':
            dp[(index, current_string)] = backtrack(index + 1, current_string + s[index])
            return dp[(index, current_string)]

        count = 0
        for char in ['A', 'B']:
            count += backtrack(index + 1, current_string + char)
            count %= MOD
        dp[(index, current_string)] = count
        return count

    return backtrack(0, '')
