def count_k_reducible(s: str, k: int) -> int:
    MOD = 10**9 + 7

    def is_k_reducible(n, k):
        visited = set()
        while k > 0:
            if n == 1:
                return True
            if n in visited:
                return False
            visited.add(n)
            n = bin(n).count('1')
            k -= 1
        return n == 1

    count = 0
    n = int(s, 2)
    for i in range(1, n):
        if is_k_reducible(i, k):
            count += 1
    return count % MOD
