import heapq

def minimize_path_weights(n: int, edges: List[Tuple[int, int, int]], a: List[int], b: List[int]) -> int:
    # Create a dictionary to store the edges
    graph = {i: {} for i in range(1, n + 1)}
    for u, v, w in edges:
        graph[u][v] = w
        graph[v][u] = w  # Since the graph is undirected

    # Function to find the minimum possible path weight from vertex x to vertex y
    def f(x, y):
        # Use a priority queue to perform a modified Dijkstra's algorithm
        distances = {i: float('inf') for i in range(1, n + 1)}
        distances[x] = 0
        queue = [(0, x)]
        while queue:
            current_distance, current_vertex = heapq.heappop(queue)
            if current_distance > distances[current_vertex]:
                continue
            for neighbor, weight in graph[current_vertex].items():
                distance = max(current_distance, weight)
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(queue, (distance, neighbor))
        return distances[y]

    # Find the minimum possible sum of f(a[i], b[i]) for all i
    min_sum = float('inf')
    for permutation in itertools.permutations(b):
        total_weight = sum(f(a[i], permutation[i]) for i in range(len(a)))
        min_sum = min(min_sum, total_weight)

    return min_sum
