def count_subsequence_pairs(nums: List[int]) -> int:
    count = 0
    n = len(nums)
    total = 2 ** n

    for mask1 in range(1, total):
        for mask2 in range(1, total):
            # Check if the two subsets are disjoint
            if (mask1 & mask2) == 0:
                seq1 = [nums[i] for i in range(n) if (mask1 >> i) & 1]
                seq2 = [nums[i] for i in range(n) if (mask2 >> i) & 1]

                # Check if both subsequences are non-empty
                if seq1 and seq2:
                    gcd_seq1 = gcd_list(seq1)
                    gcd_seq2 = gcd_list(seq2)

                    if gcd_seq1 == gcd_seq2:
                        count += 1

    # Avoid counting the same pair twice
    return count // 2 % (10**9 + 7)

