    n = len(s)

    def is_semi_palindrome(substring):
        length = len(substring)
        for d in range(1, length):
            if length % d == 0:
                for i in range(d):
                    group = substring[i:length:d]
                    if group != group[::-1]:
                        break
                else:
                    return True
        return False

    def min_changes(substring):
        min_changes = float('inf')
        length = len(substring)
        for d in range(1, length):
            if length % d == 0:
                changes = 0
                for i in range(d):
                    group = substring[i:length:d]
                    for j in range(len(group) // 2):
                        if group[j] != group[-j - 1]:
                            changes += 1
                min_changes = min(min_changes, changes)
        return min_changes

    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            for m in range(j - 1, i):
                substring = s[m:i]
                if len(substring) >= 2 and is_semi_palindrome(substring):
                    dp[i][j] = min(dp[i][j], dp[m][j-1])
                else:
                    dp[i][j] = min(dp[i][j], dp[m][j-1] + min_changes(substring))

    return dp[n][k]
