from typing import List

def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """
    Play a modified tic-tac-toe game on a 3x3 grid where each cell has a value.

    Takahashi (first player) and Aoki (second player) take turns choosing white cells.
    When a player chooses a cell, they score the points in that cell and paint it their color
    (Takahashi: red, Aoki: blue).

    The game ends when:
    - A player gets 3 consecutive cells of their color (row/column/diagonal) - that player wins
    - All cells are painted - the player with higher total score wins

    Both players play optimally. The sum of all values in the grid is guaranteed to be odd.

    Args:
        grid: A 3x3 grid of integers representing cell values

    Returns:
        "Takahashi" if Takahashi wins, "Aoki" if Aoki wins
    """

    # Initialize the scores for Takahashi and Aoki
    takahashi_score = 0
    aoki_score = 0

    # Function to check if a player has won
    def has_won(grid, player):
        # Check rows and columns for a win
        for i in range(3):
            if grid[i][0] == grid[i][1] == grid[i][2] == player:
                return True
            if grid[0][i] == grid[1][i] == grid[2][i] == player:
                return True

        # Check diagonals for a win
        if grid[0][0] == grid[1][1] == grid[2][2] == player:
            return True
        if grid[0][2] == grid[1][1] == grid[2][0] == player:
            return True

        return False

    # Function to calculate the score of a player
    def calculate_score(grid, player):
        score = 0
        for i in range(3):
            for j in range(3):
                if grid[i][j] == player:
                    score += abs(grid[i][j])
        return score

    # Simulate the game
    for _ in range(9):
        max_val = float('-inf')
        max_pos = None
        for i in range(3):
            for j in range(3):
                if grid[i][j] != 0 and grid[i][j] != -1 and grid[i][j] != -2:
                    if grid[i][j] > max_val:
                        max_val = grid[i][j]
                        max_pos = (i, j)

        # Takahashi's turn
        if _ % 2 == 0:
            grid[max_pos[0]][max_pos[1]] = -1
            if has_won(grid, -1):
                return "Takahashi"
        # Aoki's turn
        else:
            grid[max_pos[0]][max_pos[1]] = -2
            if has_won(grid, -2):
                return "Aoki"

    # If all cells are painted, the player with the higher score wins
    takahashi_score = calculate_score(grid, -1)
    aoki_score = calculate_score(grid, -2)
    if takahashi_score > aoki_score:
        return "Takahashi"
    elif aoki_score > takahashi_score:
        return "Aoki"
    else:
        return "Takahashi"

